mapper.select:
/*selectBuyerMdCmCategoryPCO*/ SELECT Z.IMGFILE_NAME, Z.IMGFILE_DIR, Z.BUYER_ITEM_NO, Z.DESCRIPTION_LOC, Z.SPECIFICATION, Z.ORIGIN_NAME, Z.MAKER_NAME, Z.UNIT_MEASURE, Z.TARGET_PRICE, Z.CATEGORY_NO, DECODE(NVL(Z.AGENT,'MULTI'),'MULTI','복수공급사입니다','+','복수공급사입니다',Z.AGENT) AGENT, Z.STDCATLG_ID, DECODE(NVL(Z.AGENT2,'MULTI'),'MULTI','MULTI_AGENT',Z.AGENT2) AGENT2, Z.CONTRACT_NO, DECODE(NVL(Z.CONTRACT_SEQ,'MULTI'),'MULTI','MULTI_SEQ',Z.CONTRACT_SEQ) CONTRACT_SEQ, Z.BUYER, Z.STDCATEG_ID, Z.ORG_BUYER_ITEM_NO, Z.GUBUN, Z.LIST_PRICE, Z.OVER_SHORT_FLAG, Z.HS_NO, Z.STOCK_QTY, Z.PRODUCT_FLAG, Z.PRODUCT_CLOSE_FLAG, Z.GREEN_FLAG, Z.STOCK_FLAG, Z.ITEM_NO_TEXT2 FROM (SELECT Y.IMGFILE_NAME, Y.IMGFILE_DIR, Y.BUYER_ITEM_NO, Y.DESCRIPTION_LOC, Y.SPECIFICATION, Y.ORIGIN_NAME, Y.MAKER_NAME, Y.UNIT_MEASURE, Y.TARGET_PRICE, Y.CATEGORY_NO, Y.AGENT, Y.STDCATLG_ID, Y.AGENT2, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BUYER, Y.STDCATEG_ID, Y.ORG_BUYER_ITEM_NO, Y.GUBUN, Y.LIST_PRICE, Y.OVER_SHORT_FLAG, Y.HS_NO, Y.STOCK_QTY, Y.PRODUCT_FLAG, Y.PRODUCT_CLOSE_FLAG, Y.GREEN_FLAG, Y.STOCK_FLAG, Y.ITEM_NO_TEXT2 FROM (SELECT X.IMGFILE_NAME, X.IMGFILE_DIR, X.BUYER_ITEM_NO, MAX(X.DESCRIPTION_LOC) DESCRIPTION_LOC, MAX(X.SPECIFICATION) SPECIFICATION, X.ORIGIN_NAME, X.MAKER_NAME, X.UNIT_MEASURE, X.TARGET_PRICE, X.CATEGORY_NO, P.COM_NAME_LOC AGENT, X.STDCATLG_ID, P.COM_CODE AGENT2, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BUYER, X.STDCATEG_ID, MAX(X.ORG_BUYER_ITEM_NO) ORG_BUYER_ITEM_NO, MAX(X.GUBUN) GUBUN, MAX(X.LIST_PRICE) LIST_PRICE, MAX(X.OVER_SHORT_FLAG) OVER_SHORT_FLAG, MAX(X.HS_NO) HS_NO, MAX(X.STOCK_QTY) STOCK_QTY, MAX(X.PRODUCT_FLAG) PRODUCT_FLAG, MAX(X.PRODUCT_CLOSE_FLAG) PRODUCT_CLOSE_FLAG, MAX(X.GREEN_FLAG) GREEN_FLAG, MAX(X.STOCK_FLAG) STOCK_FLAG, MAX(DECODE(X.ITEM_NO_CNT,'0','가능','진행중')) ITEM_NO_TEXT2 FROM ( SELECT TRIM(B.IMGFILE_NAME) IMGFILE_NAME, TRIM(B.IMGFILE_DIR) IMGFILE_DIR, C.ITEM_NO AS BUYER_ITEM_NO, B.DESCRIPTION_LOC, B.SPECIFICATION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE) ORIGIN_NAME, B.MAKER_NAME, B.UNIT_MEASURE, C.TARGET_PRICE, B.CATEGORY_NO, DECODE((SELECT COUNT(DISTINCT AGENT) FROM ICOMCQDT WHERE C.BUYER = BUYER AND C.BUYER_ITEM_NO = BUYER_ITEM_NO), 1, C.AGENT,'+') AGENT, C.STDCATLG_ID, C.CONTRACT_NO, DECODE((SELECT COUNT(DISTINCT CONTRACT_SEQ) FROM ICOMCQDT WHERE C.BUYER = BUYER AND C.BUYER_ITEM_NO = BUYER_ITEM_NO), 1, C.CONTRACT_SEQ,'+') CONTRACT_SEQ, B.BUYER BUYER, B.STDCATEG_ID, C.BUYER_ITEM_NO ORG_BUYER_ITEM_NO, DECODE(C.ITEM_NO,NULL,'비재고','재고가능') AS GUBUN, C.LIST_PRICE LIST_PRICE, B.OVER_SHORT_FLAG, B.HS_NO, '0' STOCK_QTY, DECODE(B.PRODUCT_CLOSE_FLAG,'N','단가계약품목','A','일회성_미발주','C','신규요청품목','Y','단종') PRODUCT_FLAG, B.PRODUCT_CLOSE_FLAG, B.GREEN_FLAG, DECODE(C.S_STOCK_FLAG,'Y',(SELECT NVL(STOCK_QTY,0) FROM KEP_S_STOCK WHERE BUYER = C.BUYER AND BUYER_ITEM_NO = C.BUYER_ITEM_NO AND SELLER = C.AGENT),'') STOCK_FLAG, (SELECT COUNT(*) FROM KEPRQDT WHERE BUYER = C.BUYER AND RECV_FLAG NOT IN ('GD','CM') AND BUYER_ITEM_NO = C.BUYER_ITEM_NO) AS ITEM_NO_CNT FROM ICOMBYIT B, ICOMCQDT C
WHERE B.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.STDCATLG_ID = C.STDCATLG_ID AND B.BUYER =#{st_buyer} AND B.BUYER = C.BUYER AND B.STATUS <> 'D' AND C.STATUS <> 'D'
AND SUBSTR(B.CATEGORY_NO,0,1) = 'R'
AND B.PRODUCT_CLOSE_FLAG IN ('N','C','A') AND B.CATEGORY_NO =#{st_categ_id} ORDER BY B.PRODUCT_CLOSE_FLAG desc,C.BUYER_ITEM_NO ) X, ICOMCMPY P WHERE X.AGENT = P.COM_CODE(+) GROUP BY X.IMGFILE_NAME, X.IMGFILE_DIR, X.BUYER_ITEM_NO, X.ORIGIN_NAME, X.MAKER_NAME, X.UNIT_MEASURE, X.TARGET_PRICE, X.CATEGORY_NO, P.COM_NAME_LOC, X.STDCATLG_ID, P.COM_CODE, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BUYER, X.STDCATEG_ID ) Y) Z
ORDER BY ${st_sort_column} ${st_sort_flag}
ORDER BY 26 DESC,19
